{
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebApplication",
      "name": "Tools X",
      "url": "https://www.toolsx.in/",
      "description": "Discover free AI tools, developer utilities, multimedia editors, and expert tech guides at ToolsX.in.",
      "applicationCategory": "Utility",
