}

//
(function(){
  // TSXv5.2 FIX: default is now LIGHT mode for every new visitor. Reading the saved
  // preference is wrapped in its OWN try/catch so that if localStorage is blocked
  // (e.g. Blogger's sandboxed Preview iframe, or a browser privacy setting), the read
  // simply fails and we fall through to light — the attribute always still gets set,
  // instead of the old code where a blocked localStorage read aborted the whole try
  // block and skipped setAttribute entirely, leaving the page on unscoped/light CSS
  // even when dark was meant to be the default.
  var t = 'light';   // Light Mode default
  try{
    var stored = localStorage.getItem('ai-theme');
    if(stored === 'dark' || stored === 'light'){ t = stored; }
  }catch(e){}
  document.documentElement.setAttribute('data-theme', t);
})();
//

b:if.b:skin:
  body, html {
    overflow-x: hidden !important;
    width: 100% !important;
  }
  .outer-container, .container, #outer-container, #wrapper, .content-wrapper {
    width: 100% !important;
    max-width: 100% !important;
    padding-left: 10px !important;
    padding-right: 10px !important;
    box-sizing: border-box !important;
    margin: 0 auto !important;
  }
  img, video, iframe, embed, object {
    max-width: 100% !important;
    height: auto !important;
  }
  table {
    width: 100% !important;
    overflow-x: auto !important;
    display: block !important;
  }
  #feed-view, #sidebar-container, .sidebar, .main-content, .post-body {
    width: 100% !important;
    max-width: 100% !important;
    float: none !important;
    box-sizing: border-box !important;
    padding: 0 5px !important;
  }
  .row, .footer-outer {
    flex-direction: column !important;
    display: flex !important;
  }
  body {
    font-size: 16px !important;
    -webkit-text-size-adjust: 100%;
  }

<Group  description="Layout Options" selector="body">
<Variable name="boxedMode" description="Enable Boxed Mode" type="length" default="0px" min="0px" max="1px" value="1px"/>
<Variable name="stickyMenu" description="Enable Sticky Header" type="length" default="1px" min="0px" max="1px" value="1px"/>
<Variable name="stickySidebar" description="Enable Sticky Sidebar" type="length" default="1px" min="0px" max="1px" value="1px"/>
</Group>
<Group description="Theme Colors" selector="body">
