#feed-view{width:calc(100% - (260px + 5px))!important}
#sidebar-container{width:260px!important}
@media screen and (max-width:880px){#feed-view,#sidebar-container{width:100%!important}}

.sidebar .widget{padding:12px!important;margin:0 0 20px!important}
.sidebar .PopularPosts .post-filter-inner.gaint{width:100%!important;height:160px!important}
.sidebar .PopularPosts .post-filter-inner{width:65px!important;height:55px!important}
.sidebar .PopularPosts .entry-title{font-size:13px!important}
.sidebar .Image img{max-width:100%!important;height:auto!important}

.footer-outer{gap:20px!important}
.footertab{width:calc((100% - 40px) / 3)!important}
@media screen and (max-width:880px){.footertab{width:100%!important}}

@media screen and (min-width:881px){
  .outer-container{max-width:1200px!important;margin:0 auto!important}
  #feed-view{flex:1!important;max-width:calc(100% - 270px)!important}
  #sidebar-container{flex:0 0 260px!important;max-width:260px!important}
  .container{max-width:1200px!important;padding:0 15px!important}
}

@media screen and (max-width:1178px){
  #outer-wrapper{max-width:100%!important}
  #center-container{padding:0 10px!important}
}

@media screen and (max-width:1078px){
  #outer-wrapper{max-width:100%!important}
  .header-right{position:absolute!important;right:0!important}
  .header-section{justify-content:flex-start!important}
}

@media screen and (max-width:880px){
  #feed-view,#sidebar-container{width:100%!important;max-width:100%!important;flex:none!important}
  .outer-container{flex-direction:column!important}
  .post-filter-wrap .grid-posts{grid-column-gap:10px!important}
  .imaiIf.item0 .post-filter-inner{height:265px!important}
  .footertab{width:100%!important}
  .footer-primary{flex-direction:column!important}
  .bio-data{width:100%!important;text-align:center!important}
  .footer-primary .Image{width:100%!important}
  .footer-outer{flex-direction:column-reverse!important;gap:0!important}
}

@media screen and (max-width:768px){
  .ijoiIf .widget .post-filter-inner{height:340px!important}
  .rbrwzo{flex-direction:column!important}
  .rbrkio.item0,.block-combo{width:100%!important}
  .livVrSii{grid-gap:5px!important}
  .livVikii{grid-template-columns:repeat(1,1fr)!important}
  .rbrkio.item0 .post-filter-inner,.imaiIf.item0 .post-filter-inner{margin:0 0 15px!important}
  .xlilo .avatar-container{float:none!important;margin:10px auto!important}
  .author-name{text-align:center!important}
  .xliilo{text-align:center!important}
  .description-links li{float:none!important;display:inline-block!important}
  .post-footer{margin:0!important}
  .my-sidebar{grid-gap:7px!important}
  .iLoiIf .widget,.post-filter-wrap,.sidebar .widget{padding:15px 5px!important}
  #llmflii .footer{width:100%!important;margin-right:0!important}
}

@media screen and (max-width:680px){

  .idea-box .widget{width:calc((100% - 15px) / 2)!important}
  .piki-hero-flow .post-snippet{display:none!important}
  #xliiv{right:0!important;left:0!important;bottom:0!important;width:initial!important;margin:0!important;padding:20px 15px!important;border-radius:0!important}
}

@media screen and (max-width:640px){
  div#mega-wrap{max-width:100%!important}
  .ijoiIf .widget .post-snip{font-size:12px!important}
  a.read-more{display:none!important}
  .ijoiIf .widget .post-filter-inner{width:100%!important}
  .ijoiIf .widget .widget-content{min-height:350px!important}
  .ifaiIf .entry-title{font-size:16px!important;font-weight:500!important}
  .frRlLii,.ifaiIf{margin:0!important}
  .ijoiIf .buttons-fix a{height:20px!important;width:20px!important;font-size:20px!important}
  .header-room img{max-height:35px!important}
  .post-filter-wrap .grid-posts{grid-template-columns:1fr!important}
  .post-filter{margin:5px 0!important}
  .post-filter .post-filter-link,.imaiIf .post-filter-inner{height:115px!important;width:175px!important}
  .iLoiIf .raw-main{width:100%!important;clear:both!important}
  .rmffsio{width:100%!important;margin:0 0 10px!important}
  .iLoiIf .llhvihi.item0 .entry-title{font-size:20px!important}
  .rbrkio.item0 .post-filter-inner{height:332px!important}
  .rmffsio .block-thumb .post-filter-link{height:150px!important}
  .StickyDemo{margin:0 4px!important}
  .zZiilz.zeicilo li{width:33%!important}
  .zZiilz.zeicilo a:before{font-size:19px!important}
  .zZiilz.zeicilo li a{height:30px!important;line-height:20px!important}
  .zZiilz.zeicilo{padding:10px 0px 20px!important}
  input.search-input{font-size:20px!important}
  .iLoiIf-content{padding:0!important}
  #feed-view #main{margin:0!important}
  .post-filter .entry-title,.iLoiIf .entery-category .entry-title{font-size:15px!important}
  .related-runs .ijfbiIf,#room-box .liimikii .imaiIf{width:100%!important}
  .related-runs .ijfbiIf .ijfbiIf-thumb{height:250px!important}
  .post-snip{margin:10px 10px 0 0!important}
  .date-format{width:52px!important;padding:0 3px 0!important;margin:0!important}
  .dstyle.v1{font-size:15px!important}
  .dstyle.v2{font-size:11px!important}
}

@media screen and (max-width:480px){
  .ijyciIf{display:block!important}
  .post-image{height:190px!important}
  .card-wrap{display:block!important;flex-direction:column!important;align-items:start!important}
  a.card-button.main-button{display:block!important;max-width:100%!important}
  .card-header{justify-content:flex-start!important}
  .rbrkio.item0 .post-filter-inner{height:270px!important}
  .llhvihi.item0 .post-filter-inner{height:265px!important}
  .llhvihi .post-filter-inner{width:120px!important;height:105px!important}
  .item-post .post-inner-area h1.entry-title{font-size:24px!important}
  .description-links li{float:none!important;display:inline-block!important;margin:10px!important}
  .errorPage{padding:70px 0 100px!important}
  .errorPage h3{font-size:120px!important}
  #comments ol{padding:0!important}
  .post-filter .post-filter-link,.imaiIf .post-filter-inner{height:100px!important;width:135px!important}
  .ai-theme-toggle{bottom:70px!important;right:15px!important;width:40px!important;height:40px!important}
  .ai-back-to-top{bottom:15px!important;right:15px!important;width:35px!important;height:35px!important}
}

@media screen and (max-width:380px){
  .pagination .btn{min-width:unset!important;font-size:0!important}
  .llhtsihi{width:100px!important;height:80px!important}
  .ijoiIf .widget .widget-content{min-height:250px!important}
  .ijoiIf .widget .post-filter-inner{height:250px!important}
  .livVrSii{display:block!important}
  .xlilo .avatar-container{width:60px!important;height:60px!important}
  .item .comment-bubble{display:none!important}
  .share-top{margin:0!important}
}

html,body,#outer-wrapper,.post-inner-area,.widget,.sidebar,#llhflii,div.llhbflii,
.post-filter-wrap,.blog-posts,.iLoiIf .widget,.related-runs,.xlilo,.comment-contentl,
