html[data-theme='dark'] div#mega-wrap{background:linear-gradient(282deg,rgb(90 30 130 / 0.35),rgb(20 60 90 / 0.35),rgb(30 40 110 / 0.4))!important;}
html[data-theme='dark'] .axil-shape.v1{background:rgb(255 255 255 / 0.04)!important}
html[data-theme='dark'] .axil-shape.v2{background:rgb(25 170 255 / 0.12)!important}
html[data-theme='dark'] .axil-shape.v0,html[data-theme='dark'] .axil-shape.v3{background:rgb(163 116 255 / 0.14)!important}
html[data-theme='dark'] .axil-svg{opacity:0.55;filter:brightness(0.75) saturate(0.85)}

html[data-theme='dark'] .ai-skeleton{background:linear-gradient(90deg,#1e1e1e 25%,#2a2a2a 50%,#1e1e1e 75%)!important;background-size:200% 100%}

html[data-theme='dark'] .zeitvilo{background:linear-gradient(135deg,rgb(0 79 255 / 0.16),rgb(141 93 249 / 0.16))!important}

html[data-theme='dark'] h1,html[data-theme='dark'] h2,html[data-theme='dark'] h3,html[data-theme='dark'] h4,html[data-theme='dark'] h5,html[data-theme='dark'] h6{color:var(--main-text-color)}
html[data-theme='dark'] p,html[data-theme='dark'] span,html[data-theme='dark'] li,html[data-theme='dark'] a{color:inherit}
