.header-room{display:flex;flex-wrap:wrap;flex-direction:row;justify-content:center;align-items:center;align-content:center;margin:0;}
.date-format{display:flex;align-items:center;justify-content:center;color:var(--main-menu-text-color);width:74px;padding:0 5px 0;margin:0 0 0 8px;border-left:1px solid rgb(110 110 110 / 0.36);}
.rtl .date-format{border-left:unset;border-right:1px solid rgb(110 110 110 / 0.36);}
.dstyle.v1{font-size:21px;}
.dstyle.v2{display:flex;flex-direction:column;font-size:14px;line-height:17px;align-items:center;margin:0 5px;}
.zeitdilo{position:relative;background-color:rgb(0 0 0 / 0.36);display:flex;align-items:center;font-size:12px;color: var(--button-text-color);width:40px;height:20px;margin:0 5px;border-radius:20px;}
.zeitdilo:hover:before{opacity:0.8}
.zeitdilo:before{content:'\e518';font-family:'Material Icons Round';position:absolute;left:2px;width:16px;height:16px;text-align:center;background-color:var(--button-bg-color);font-weight:400;line-height:16px;z-index:2;border-radius:50%;box-shadow:0 0 4px rgb(0 0 0 / 0.10);transition:left .18s ease;}
.zeitdilo:after{content:'\ea46';font-family:'Material Icons Round';position:absolute;right:4px;width:10px;font-size:8px;font-weight:400;line-height:1;text-align:center;opacity:0.5;transition:right .18s ease;}
.zeitvilo .open-iki,.zeitvilo .widget.PopularPosts .widget-content{display:flex!important;}
.zeitvilo{position:relative;margin:15px 10px;overflow:hidden;background:rgb(0 79 255 / 0.08);border-radius:4px;}
.zeitvilo .widget-content{position:relative;justify-content:flex-end;flex:1;align-items:center;margin:0;display:none;height:40px;overflow:hidden;}
.zeitvilo .widget{display:block;height:40px;padding:5px 0;margin:0;}
.zeitvilo .widget>.widget-title{display:block;position:relative;float:left;height:40px;line-height:40px;padding:0 10px;margin:0 10px 0 5px;border-right:1px solid rgba(0 0 0 / 0.18);}
.zeitvilo .widget>.widget-title>h3{display:flex;align-items:center;font-size:16px;font-weight:700;color:var(--theme-text-color);line-height:40px;margin:0;gap:5px;}
.zeitvilo .widget>.widget-title>h3:before{content:'\ea0b';font-family:'Material Icons Round';float:left;font-size:12px;font-weight:400;margin:0;text-align:center;width:16px;height:16px;border-radius:50%;background:var(--button-bg-color);color:var(--button-text-color);line-height:17px;}
.rtl .zeitvilo .widget>.widget-title{float:right;border-right:unset;border-left:1px solid rgba(0 0 0 / 0.18);}
.brRlLii{position:relative;display:flex;box-sizing:border-box;justify-content:space-between;flex:1;margin:0;height:40px;}
.zeitvilo .loading-icon:after{width:20px;height:20px;}
.brRlLii .active{opacity:1;visibility:visible;transform:translate3d(0,0,0);pointer-events:initial}
.itaiIf .post-filter-inner{position:relative;display:block;float:left;width:40px;height:40px;overflow:hidden;margin:0 10px 0 0;border-radius:50%;}
.itaiIf .post-filter-inner .post-filter-link{display:block;width:100%;height:100%;overflow:hidden;}
.itaiIf .entery-category{padding:0;}
.rtl .itaiIf .entery-category{float:left;}
.rtl .zeitvilo .widget>.widget-title>h3:before{margin: 0 0 0 3px;}
.itaiIf .entery-category .entry-title{display:block;font-size:16px;line-height:28px;margin:5px 0;}
.itaiIf{position:absolute;top:0;left:0;opacity:0;visibility:hidden;pointer-events:none;transform:translate3d(10px,0,0);transition:all .80s ease}
.zeitvilo .buttons-fix{display:flex;flex-direction:row;align-items:center;justify-content:space-around;margin:0 10px 0 0;height:30px}
.buttons-fix>a{display:flex;width:20px;height:20px;line-height: 20px;font-size:21px;text-align:center;margin:0 2px;padding:5px;cursor:pointer;color:var(--bt-breaking-text);background:var(--bt-breaking);border-radius: 4px;}
.zeitvilo .buttons-fix>a{background:var(--main-menu-bg);color:var(--main-menu-text-color);}
.buttons-fix>a:hover{opacity:0.8;}
.buttons-fix .prev:before, .buttons-fix .pv:before{content:'\e5cb'}
.buttons-fix .next:before, .buttons-fix .nt:before{content:'\e5cc'}
.buttons-fix a:before{display:block;font-family:'Material Icons Round';margin:auto;text-align:center;font-weight:400}
.entery-category-box {overflow: hidden;}
.entery-category-box .entry-title{position:relative;display:block;font-size:19px;line-height:1.5;margin:5px 0;}
.entery-category-box .entry-title a,.post-filter .entry-title a{width:100%;overflow:hidden;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;}
#menutab>.mega-menu{position:unset!important}
.llhpflim li:hover .my-menu{opacity:1;visibility:visible}
.drop-down>a:after{content:'\e5cf';float:right;font-family:'Material Icons Round';font-size:9px;font-weight:400;margin:-1px 0 0 5px}
.my-menu{position:absolute;background-color:var(--block-bg);top:59px;opacity:0;visibility:hidden;width:100%;left:0;box-sizing:border-box;border-radius:4px;right:0;z-index:3333;color:var(--white-bg);height:auto;padding:20px;min-height:100px;box-shadow:0 10px 10px rgba(0,0,0,0.28);transition:all .3s ease;}
.llhpflim li:hover .my-menu{margin-top:1px;opacity:1;visibility:visible}
