.ijfbiIf .ijfbiIf-thumb .post-filter-link{position:relative;width:100%;height:100%;display:block;overflow:hidden}
.ijfbiIf .ijfbiIf-thumb{width:100%;height:130px;display:block;overflow:hidden;border-radius: 4px;}
.blog-posts .widget-title,.title-wrap,.related-runs .widget-title{display:flex;justify-content:space-between;align-items:center;}
a.more-c{color:var(--theme-text-color);font-size:13px;font-weight:600;}
.ijoiIf .widget{display:none;float: left;width: 100%;box-sizing: border-box;border-radius:10px;padding:7px;}
.ijoiIf .widget.PopularPosts,.ijoiIf .open-iki{display:block!important}
.ijoiIf .widget .widget-content{position:relative;float: left;width: 100%;overflow:hidden;min-height:490px;}
.iLoiIf .imaiIf.item0 .entry-title,.iLoiIf .llhvihi.item0 .entry-title{font-size:25px}
.ifaiIf .entry-title{font-size:30px}
.ijoiIf .widget .post-snip{font-size:17px;}
.ijoiIf .widget img.post-author-image{height:26px;width:26px;}
.axil-shape{position:absolute;width:35.7rem;height:35.7rem;border-radius:50%;-webkit-transform:scale(1);-ms-transform:scale(1);transform:scale(1);-webkit-transition:all 1s;-o-transition:all 1s;transition:all 1s;}
.axil-shape.v1{background:rgb(100 100 100 / 0.08);top:-120px;left:-120px;}
.axil-shape.v2{background:rgb(25 170 255 / 0.10);bottom:-120px;right:-120px;}
.axil-shape.v0,.axil-shape.v3{background:rgb(163 116 255 / 0.08);}
.axil-shape.v3{width:30.7rem;height:30.7rem;}
.axil-svg{position:absolute;top:0;right:0;}
.news-highlights-row{display:flex;flex-direction:column;align-items:center;gap:20px;width:100%;box-sizing:border-box;}
.news-highlights-row>.ticker.flex-section{flex:1 1 100%;max-width:100%;width:100%;}
.news-highlights-row>div#mega-wrap{flex:none;max-width:900px;width:100%;margin:0 auto;}
@media screen and (max-width:900px){
  .news-highlights-row{flex-direction:column;}
  .news-highlights-row>.ticker.flex-section,.news-highlights-row>div#mega-wrap{flex:1 1 100%;max-width:100%;}
  div#flex-idea{margin-top:20px!important;}
}
div#mega-wrap{position:relative;background:linear-gradient(282deg,rgb(241 37 255 / 0.12),rgb(44 255 245 / 0.12),rgb(31 69 255 / 0.17));padding:30px 0;max-width:100%;margin:0;box-sizing:border-box;clear:both;float:none;border-radius:10px;overflow:hidden;}
.frRlLii{position:relative;display:block;margin:0 45px;box-sizing:border-box;}
.ifaiIf{display:flex;flex-direction:row-reverse;align-items:center;justify-content:space-between;align-content:center;margin:40px 0 40px;}
.ijoiIf .buttons-fix{z-index:1;}
.ijoiIf .buttons-fix a{position:absolute;top:50%;height:30px;width:30px;transform:translateY(-50%);background-color:rgb(82 89 141 / 0.42);font-size:28px;color: #fff;}
.ijoiIf .buttons-fix a:hover{background-color:var(--button-bg-color);color:var(--button-text-color);}
.ijoiIf a.pv{left:0;}
.ijoiIf a.nt{right:0;}
.ijoiIf .widget .post-tag{font-size:14px;padding:5px 11px;}
.ifaiIf{position:absolute;top:0;left:0;opacity:0;width:100%;visibility:hidden;pointer-events:none;transform:translate3d(10px,0,0);transition:all .80s ease;}
.ifaiIf .snip-thumbnail{background:rgb(98 98 98 / 0.32);}
.ijoiIf .ifaiIf.active{opacity:1;visibility:visible;transform:translate3d(0,0,0);pointer-events:initial;}
.ifaiIf.item1{grid-row:1/3;grid-column:1/2;}
.ifaiIf.item2{grid-row:1/3;grid-column:2/3;}
.ifaiIf .entery-category-fly{bottom: 15px;}
.livVikii{position: relative;display:grid;grid-template-columns:repeat(2,1fr);grid-gap:20px;border-top: 1px solid rgb(255 255 255 / 0.21);}
.llhvihi{position:relative;display:block;overflow:hidden;margin:10px 0 0;}
.llhvihi .post-filter-inner{position:relative;float:left;width:180px;height:145px;display:block;overflow:hidden;border-radius:10px;}
.llhvihi.item0 .post-filter-inner{width:100%;height:350px;}
.video-box .llhvihi:not(:last-child) a.post-filter-inner{margin:0 0 10px;}
.video-box .llhvihi:not(:last-child){border-bottom:1px solid rgb(255 255 255 / 0.21);}
.video-box:before{content:'';position:absolute;left:0;right:0;margin:0 auto;border:1px solid var(--button-bg-color);height:100%;width:1px;margin-left:auto;margin-right:auto;text-align:center;top:0;}
.llhvihi .post-filter-inner .post-filter-link{width:100%;height:100%;position:relative;display:block;overflow:hidden;}
.post-tag-color{display:block;color:var(--lables-buttons-color);font-size:13px;font-weight:600;}
.ijoiIf .widget .post-filter-link{width:100%;height:410px;position:relative;display:block;overflow:hidden;}
.ijoiIf .widget .post-filter-inner{width:535px;height:100%;display:block;overflow:hidden;border-radius: 10px;}
.ijoiIf .widget .entery-category{width: 400px;}
.iLoiIf .widget{float:left;background:var(--bg-widgets);width:100%;padding:15px;border-radius:10px;margin:0 0 15px;box-sizing:border-box}
.iLoiIf .widget-title{display:flex;flex-direction:row;align-content:center;justify-content:space-between;align-items:center;}
.iLoiIf .imaiIf .post-filter-link,.iLoiIf .rbrkio .post-filter-link{height:100%;width:100%;display:block}
.blog-posts .widget-title,.iLoiIf .widget-title,.title-wrap,.sidebar .widget-title,.related-runs .widget-title{position:relative;float:none;width:100%;height:32px;box-sizing:border-box;margin:0 0 14px;}
.blog-posts .widget-title h3,.iLoiIf .widget-title h3,.sidebar .widget-title h3,.title-wrap h3,.related-runs .widget-title h3{position:relative;float:left;font-family:var(--title-font);height:32px;font-size:17px;color:var(--theme-text-color);text-transform:uppercase;font-weight:700;line-height:32px;padding:0 12px 0 0;margin:0;}
.blog-posts .widget-title h3:before,.iLoiIf .widget-title h3:before,.sidebar .widget-title h3:before,.title-wrap h3:before,.related-runs .widget-title h3:before{content:"";height:4px;width:60px;background-color:var(--button-bg-color);position:absolute;bottom:0;left:0;border-radius:10px;}
.blog-posts .widget-title h3:after,.iLoiIf .widget-title h3:after,.sidebar .widget-title h3:after,.title-wrap h3:after,.related-runs .widget-title h3:after{content:"";height:5px;width:5px;background-color:var(--button-bg-color);position:absolute;bottom:-1px;left:65px;border-radius:50px;}
.rtl .blog-posts .widget-title h3,.rtl .iLoiIf .widget-title h3,.rtl .sidebar .widget-title h3,.rtl .related-runs .widget-title h3{float:right;padding: 0 0 0 12px;}
.rtl .blog-posts .widget-title h3:before,.rtl .iLoiIf .widget-title h3:before,.rtl .sidebar .widget-title h3:before,.rtl .title-wrap h3:before,.rtl .related-runs .widget-title h3:before{left:initial;right:0;}
.rtl .blog-posts .widget-title h3:after,.rtl .iLoiIf .widget-title h3:after,.rtl .sidebar .widget-title h3:after,.rtl .title-wrap h3:after,.rtl .related-runs .widget-title h3:after{left:initial;right:65px;}
.sidebar .PopularPosts .gaint h2.entry-title{font-size:16px;}
.error-status{display:block;text-align:center;font-size:13px;color:var(--theme-text-color);padding:35px 0;font-weight:600}
.error-status b{font-weight:600}
.type-video .error-status{--theme-text-color:#fff}
.wait{font-size:14px;text-align:center;height:300px;line-height:300px;display:flex;justify-content:center;align-items:center}
.related-runs .ijfbiIf{width:31%;position:relative;margin:0;}
.my-sidebar{position:relative;float:left;width:100%;display:block;}
.my-sidebar .sidebartab{position:relative;float: left;width: 100%;margin: 0 0 10px;}
.my-sidebar .sidebartab .glax-img{position:relative;width:95px;height:75px;float:left;margin:0;overflow:hidden;border-radius:10px;}
.my-sidebar .sidebartab .entry-title{font-size:15px;display:block;font-weight:500;line-height:1.3;}
.featured-meta{position:relative;overflow:hidden;box-sizing:border-box;padding:5px 10px;}
.queryMessage{display:block;font-size:17px;font-weight:600;padding:0 0 0 10px;border-radius:4px;margin:0 0 5px;color:var(--theme-text-color);overflow:hidden;}
.queryMessage .query-info{margin:0 5px;display:flex;align-items:center;gap:5px;}
.queryMessage .search-query{font-weight:bold;text-transform:uppercase}
.queryMessage .query-info:before{content:'\e5cc';font-family:'Material Icons Round';float:left;font-size:24px;font-weight:400;margin:0;}
.queryEmpty{font-size:13px;font-weight:500;text-align:center;padding:10px 0;margin:0 0 20px}
.share-top{position:relative;display:flex;justify-content:center;align-items:center;margin:0 10px;font-size:15px;color:var(--featured-posts-title);background:rgb(128 128 128 / 0.07);width:35px;height:28px;line-height:28px;text-align:center;cursor:pointer;border:1px solid rgb(129 129 129 / 0.19);border-radius:3px;}
.post-inner-comments .share-top span{font-size:18px;}
.post-inner-area .post-snip:not(.post-inner-area .ijyciIf .post-snip){color:var(--theme-text-color);padding:10px 5px 10px;font-size:13px;border-bottom:1px solid #ccc}
.comment-bubble{margin-top:4px;color:var(--cm-count)}
.comment-bubble:after{content:"\e0b9";font-family:'Material Icons Round';vertical-align: middle;font-size:15px;font-weight:400;margin-left:5px}
.rtl .comment-bubble:after{margin:0 0 0 5px}
.post-inner-area{position:relative;float:left;width:100%;overflow:hidden;background: var(--bg-widgets);padding:15px 10px 20px;box-sizing:border-box;margin:0 0 10px;border-radius: 10px;}
.post-filter-wrap{position:relative;float:left;display:block;padding:10px;background: var(--bg-widgets);border-radius:10px;box-sizing:border-box;overflow:hidden}
.blog-post{display:flex;flex-direction:column;}
.post-filter-wrap .grid-posts{display:grid;grid-template-columns:1fr;grid-gap:15px;margin:0;}
.post-filter .post-filter-inner.video-nos:after,.post-filter-link.video-nos:after{content:"\e037";font-family:'Material Icons Round';font-size:24px;width:36px;height:36px;line-height:36px;border-radius:6px;font-weight:400;background:var(--ico-relative);color:#fff;opacity:.7;align-items:center;top:50%;right:50%;transform:translate(50%,-50%);position:absolute;z-index:111;padding:0 0 0 2px;margin:0;text-align:center;transition:background .30s ease}
.type-video .post-filter-link.video-nos:hover:after{background:#fe1111;}
.feat-posts .post-filter-link.video-nos:after,.PopularPosts .post:not(.post-0) .post-filter-link.video-nos:after,.video-box .llhvihi:not(.item0) .post-filter-inner .post-filter-link.video-nos:after,.imaiIf .post-filter-link.video-nos:after, .rmffsio .post-filter-link.video-nos:after{transform: translate(50%,-50%) scale(.4);}
.type-video .post-filter-link.video-nos:after{opacity:1;border-radius:11px;width:58px;height: 45px;line-height: 45px;}
.post-filter{position:relative;float:left;box-sizing:border-box;padding:0;margin:0;overflow:hidden;}
.post-filter .post-filter-inner{position:relative;float:left;overflow:hidden;box-sizing:border-box;border-radius:10px;padding:0;margin:0 14px 0 0;}
.post-filter .post-filter-link{position:relative;height:180px;width:295px;display:block;overflow:hidden;}
.post-filter .snip-thumbnail{display:block;position:absolute;top:50%;left:50%;max-width:none;max-height:100%;-webkit-transform:translate(-50%,-50%);transform:translate(-50%,-50%);}
.post-filter .piki-hero-flow{overflow: hidden;margin: 5px 0 0;}
.label-news-flex{color:var(--label-text-color);font-size:12px;line-height:15px;font-weight:400;white-space:normal;width:auto;padding:5px 0 0;margin:0;}
#feed-view #main{position:relative;overflow: hidden;box-sizing:border-box;margin:0 0 26px}
.fl-footer{display:flex;justify-content:space-between;flex-wrap: wrap;border-bottom: 1px solid rgb(111 164 229 / 0.22);}
.footertab{position:relative;display:flex;flex-direction:column;width:calc((100% - 90px) / 3);float:left;padding:25px 0;margin:0;}
.footertab .widget-title{position:relative;display:block;color:var(--footer-title-color);}
.footertab .widget-title h3{font-size:17px;margin:0 0 5px;}
.footer-primary{position:relative;display:flex;flex-direction:row;padding:25px 0;margin:0 0 20px;align-items:center;justify-content:space-between;border-radius: 4px;}
.footer-primary .widget{position:relative;float:left;box-sizing:border-box;margin:0 auto}
.footer-primary .Image{width: calc(100% - 320px);}
.footer-primary .Image .widget-content{position:relative;float:left;margin:0;width:100%}
.footer-primary .about-content .widget-title{position:relative;display:block;text-align: center;box-sizing:border-box;}
.footer-primary .about-content{display:flex;padding:0;box-sizing:border-box}
.footer-primary .Image .image-caption{font-size:13px;margin:0;color:var(--footer-about-text)}
#llmflii .colorful a{--all-link-color:var(--footer-about-text);}
.zeimilo a{--all-link-color:var(--mobile-text-color);}
.footer-primary .zeicilo li, .zeimilo .zeicilo li{float:left;margin:0 7px 0 0}
.footer-primary .zeicilo li:last-child, .zeimilo .zeicilo li:last-child{margin:0}
.footer-primary .zeicilo li a, .zeimilo .zeicilo li a{display:block;width:25px;height:25px;font-size:13px;border-radius: 4px;text-align:center;line-height:25px;margin:5px 0;}
.zeimilo .zeicilo li a{border:1px solid;}
.footer-primary .zeicilo li a{background:rgb(112 160 209 / 0.30);}
.footer-primary .footer-logo{display:flex;margin:0 auto;align-items:center;justify-content:center;}
.footer-primary .footer-logo a{float:left;position:relative;margin:0 0 10px;}
.footer-primary .footer-logo img{width:auto;height:auto;max-height:40px;}
.footertab.no-items{padding:0;border:0}
.bio-data{position:relative;float:left;width:70%;margin:0 15px;}
.bio-data h3{display:block;color:var(--footer-title-color);font-size:15px;line-height:20px;margin:0 0 5px;}
.footertab .popular-post{position:relative;display:block;box-sizing:border-box;padding:0 0 10px;margin:0 0 11px 10px;border-bottom:1px solid rgb(129 129 129 / 0.20);}
.footertab .popular-post.post:hover:before{box-shadow:inset 0 0 0 6px var(--button-bg-color);border-color:rgb(34 127 255 / 0.19);}
.footertab .popular-post.post:before{content:'';position:absolute;width:10px;height:10px;top:0px;left:-16px;border:2px solid rgb(86 86 86 / 0.19);border-radius:50%;transition:all .17s ease;box-shadow:inset 0 0 0 6px rgb(155 155 155 / 0.15);}
.footertab .popular-post h2{position:relative;display:block;font-size:14px;font-weight:600;line-height:20px;margin:0;}
.footertab .popular-post h2 a{color:var(--footer-title-color);}
.footertab .popular-post{color:var(--footer-about-text);}
.footertab .sidebar-posts{position:relative;float:left;width:100%;border-left:2px solid rgb(143 143 143 / 0.28);}
.footertab .popular-post.post:last-child{border:none;}
.footertab.list .LinkList ul li,.footertab.list .PageList ul li{position:relative;display:block;margin:10px 0;}
.footertab.list .LinkList ul li a,.footertab.list .PageList ul li a{font-size:14px;color:var(--footer-title-color);}
.footertab.list .LinkList ul li a:before,.footertab.list .PageList ul li a:before{color:var(--footer-title-color);}
.footertab .loading-icon{height:180px;}
.footertab .LinkList{margin: 15px 0 0;}
.zeimilo{float:left;width:100%;position:relative;box-sizing:border-box;}
.post-snippet{position:relative;color:var(--post-snip-data);font-size:13px;line-height:1.6;font-weight:400;margin:10px 0}
a.read-more{display:flex;width:fit-content;background:var(--button-bg-color);color:var(--button-text-color);padding:11px 20px;font-size:17px;font-weight:400;margin:15px 0 0;border-radius:8px;}
a.read-more:hover{opacity:0.8}
.CSS_LAYOUT_COMPONENT{color:rgba(0,0,0,0)!important}
#breadcrumb{font-size:13px;font-weight:400;color:#aaa;margin:0 0 10px}
#breadcrumb a{color:#aaa;transition:color .40s}
#breadcrumb a:hover{opacity:0.8}
#breadcrumb a,#breadcrumb em{display:inline-block}
#breadcrumb .delimiter:after{content:'\e5cc';font-family:'Material Icons Round';font-size:14px;font-weight:400;font-style:normal;vertical-align:middle;margin:0}
.item-post .post-inner-area h1.entry-title{color:var(--theme-text-color);text-align:left;font-size:25px;line-height:1.5;font-weight:600;position:relative;display:block;margin:0 0 15px;padding:0}
.static_page .item-post .post-inner-area h1.entry-title{margin:0;border-bottom:1px solid rgb(100 100 100 / 0.12)}
.item-post .post-body{width:100%;font-family:var(--text-font);color:var(--text-font-color);font-size:15px;line-height:1.8;padding:0;margin:0}
.iLoiIf-content{position:relative;overflow:hidden;padding:0}
.crRlLii{display:flex;flex-direction:column;}
