(function(){
  'use strict';

  // Reading Progress Indicator
  var progressBar = document.createElement('div');
  progressBar.className = 'ai-progress-bar';
  progressBar.id = 'ai-progress-bar';
  document.body.appendChild(progressBar);

  // TSXv5 FIX (Lighthouse "Forced reflow"): scrollHeight/clientHeight were being
  // read on EVERY scroll event, right after a style.width write from the previous
  // tick -- that read-after-write pattern forces a synchronous layout on every
  // single scroll tick (layout thrashing), which is exactly what Lighthouse's
  // mobile performance audit flags as "Forced reflow", especially on slow
  // devices/throttled connections. Fix: cache the document height once (updated
  // only on load/resize, never on scroll), and batch ALL scroll work in this theme
  // through one shared rAF-throttled dispatcher (window.tsxOnScroll) so reads and
  // writes across every scroll listener happen at most once per animation frame
  // instead of once per raw scroll event.
  window.__tsxScrollCbs = window.__tsxScrollCbs || [];
  window.__tsxScrollTicking = false;
  window.tsxOnScroll = window.tsxOnScroll || function(cb){ window.__tsxScrollCbs.push(cb); };
  if(!window.__tsxScrollListenerAdded){
    window.__tsxScrollListenerAdded = true;
    window.addEventListener('scroll', function(){
      if(!window.__tsxScrollTicking){
        window.__tsxScrollTicking = true;
        requestAnimationFrame(function(){
          for(var i = 0; i < window.__tsxScrollCbs.length; i++){ window.__tsxScrollCbs[i](); }
          window.__tsxScrollTicking = false;
        });
      }
    }, {passive:true});
  }

  var tsxDocHeight = 0;
  function tsxUpdateDocHeight(){
    tsxDocHeight = document.documentElement.scrollHeight - document.documentElement.clientHeight;
  }
  tsxUpdateDocHeight();
  window.addEventListener('resize', tsxUpdateDocHeight, {passive:true});
  window.addEventListener('load', tsxUpdateDocHeight);

  window.tsxOnScroll(function(){
    var winScroll = document.body.scrollTop || document.documentElement.scrollTop;
    var scrolled = tsxDocHeight > 0 ? (winScroll / tsxDocHeight) * 100 : 0;
