  // ToolsX: Fix literally-displayed HTML entities in post content.
  // SECURITY: decodes entities via lookup table + numeric regex only —
  // never assigns untrusted text to innerHTML.
  var TSXV5_NAMED_ENTITIES = {
    'amp':'&','lt':'<','gt':'>','quot':'"','apos':"'",'nbsp':'\u00A0',
    'hellip':'\u2026','mdash':'\u2014','ndash':'\u2013',
    'lsquo':'\u2018','rsquo':'\u2019','ldquo':'\u201C','rdquo':'\u201D',
    'copy':'\u00A9','reg':'\u00AE','trade':'\u2122'
  };
  function tsxv5DecodeEntities(text){
    return text.replace(/&#x([0-9a-fA-F]+);/g, function(m, hex){
      return String.fromCodePoint(parseInt(hex, 16));
    }).replace(/&#(\d+);/g, function(m, dec){
      return String.fromCodePoint(parseInt(dec, 10));
    }).replace(/&([a-zA-Z]+);/g, function(m, name){
      var lower = name.toLowerCase();
      return TSXV5_NAMED_ENTITIES.hasOwnProperty(lower) ? TSXV5_NAMED_ENTITIES[lower] : m;
    });
