  function fixDisplayedHtmlEntities(){
    var postBody = document.getElementById('postBody');
    if(!postBody || !document.createTreeWalker) return;
    var entityPattern = /&#x?[0-9a-fA-F]+;|&[a-zA-Z]+;/;
    var walker = document.createTreeWalker(postBody, NodeFilter.SHOW_TEXT, null, false);
    var node;
    while((node = walker.nextNode())){
      if(node.nodeValue && entityPattern.test(node.nodeValue)){
