  // ToolsX: Post-content contrast safety net.
  // Some post content (pasted from outside tools) carries its own hardcoded
  // dark text colors that make text invisible against the dark theme
  // background. This checks the *actual rendered* color of every element
  // inside the post body and forcibly brightens anything too dark to read,
  // no matter where that color came from (inline style, embedded <style>,
  // or a class). Safe in light mode: it only runs when data-theme is dark.
  // ToolsX: Fix literally-displayed HTML entities in post content.
  // If entity codes (e.g. &#176;C or &#65039;) were typed directly into the
  // Blogger post editor, they can get double-escaped and show up as raw
  // text instead of the character they represent. This walks the post
  // body's text nodes only and decodes any leftover entity codes back into
  // real characters using a textarea (decodes text only, never runs HTML).
  // External Links Handler
  document.querySelectorAll('a[href^="http"]').forEach(function(link){
    if(link.hostname !== window.location.hostname){
      link.setAttribute('target', '_blank');
      link.setAttribute('rel', 'noopener noreferrer');
    }
  });

  // Copy Code Functionality for pre tags
  document.querySelectorAll('pre').forEach(function(pre){
    var button = document.createElement('button');
    button.className = 'copy-code-btn';
    button.textContent = 'Copy';
    pre.style.position = 'relative';
    pre.appendChild(button);

    pre.addEventListener('mouseenter', function(){button.style.opacity = '1';});
    pre.addEventListener('mouseleave', function(){button.style.opacity = '0';});

    button.addEventListener('click', function(){
      var code = pre.textContent.replace('Copy', '').trim();
      if(navigator.clipboard){
        navigator.clipboard.writeText(code).then(function(){
          button.textContent = 'Copied!';
          setTimeout(function(){button.textContent = 'Copy';}, 2000);
        });
      } else {
        var textarea = document.createElement('textarea');
        textarea.value = code;
        document.body.appendChild(textarea);
        textarea.select();
        document.execCommand('copy');
        document.body.removeChild(textarea);
        button.textContent = 'Copied!';
        setTimeout(function(){button.textContent = 'Copy';}, 2000);
      }
    });
  });

  // Smooth Scroll for Anchor Links
  document.querySelectorAll('a[href^="#"]').forEach(function(anchor){
    anchor.addEventListener('click', function(e){
      var selector = this.getAttribute('href');
      if(!selector || selector === '#') return;
      var target = null;
      try { target = document.querySelector(selector); } catch(err) { return; }
      if(target){
        e.preventDefault();
        target.scrollIntoView({behavior: 'smooth', block: 'start'});
      }
    });
  });

  //

  // Mobile Menu Toggle
  var hamburger = document.querySelector('.hamburger');
  var innerMenu = document.getElementById('inner-menu');
  var overlay = document.querySelector('.overlay');

  if(hamburger && innerMenu){
    hamburger.addEventListener('click', function(){
      document.body.classList.toggle('zsililo');
    });
    if(overlay){
      overlay.addEventListener('click', function(){
        document.body.classList.remove('zsililo');
      });
    }
  }
  // ===== MAIN MENU (NO JQUERY) =====
  function initMainMenu() {
    var menuContainer = document.getElementById('llhpflim');
    if (!menuContainer) return;

    var widget = menuContainer.querySelector('.widget');
    if (!widget) return;

    widget.classList.add('show-menu');

    var links = widget.querySelectorAll('.LinkList ul > li > a');
    var subMenus = {};

    // पहले सभी सब-मेन्यू आइटम्स को ग्रुप करें
    links.forEach(function(link) {
      var text = link.textContent.trim();
      var parentLi = link.parentElement;

      // अगर अगला लिंक "_" से शुरू होता है, तो यह सब-मेन्यू है
      var nextSibling = link.parentElement.nextElementSibling;
      if (nextSibling) {
        var nextLink = nextSibling.querySelector('a');
        if (nextLink && nextLink.textContent.trim().charAt(0) === '_') {
          var parentText = text;
          if (!subMenus[parentText]) {
            subMenus[parentText] = [];
          }
          subMenus[parentText].push(nextLink);
          nextSibling.style.display = 'none'; // छिपाएँ, बाद में दिखाएँगे
        }
      }
    });

    // अब सब-मेन्यू बनाएँ
    links.forEach(function(link) {
      var text = link.textContent.trim();
      if (subMenus[text]) {
        var parentLi = link.parentElement;
        parentLi.classList.add('sub-tab');

        var ul = document.createElement('ul');
        ul.className = 'sub-menu m-sub';

        subMenus[text].forEach(function(subLink) {
          var li = document.createElement('li');
          var a = document.createElement('a');
          a.href = subLink.href || '#';
          a.textContent = subLink.textContent.trim().replace(/^_/, '');
          li.appendChild(a);
          ul.appendChild(li);
        });

        parentLi.appendChild(ul);

        // मूल लिंक को छिपाएँ (क्योंकि अब सब-मेन्यू बन गया)
        subMenus[text].forEach(function(subLink) {
          var parentLiSub = subLink.parentElement;
          if (parentLiSub) parentLiSub.style.display = 'none';
        });
      }
    });

    // छिपे हुए सब-मेन्यू आइटम्स को पूरी तरह हटाएँ
    var allItems = widget.querySelectorAll('.LinkList ul > li');
    allItems.forEach(function(item) {
      var link = item.querySelector('a');
      if (link && link.textContent.trim().charAt(0) === '_') {
        item.style.display = 'none';
      }
    });
  }

  // पेज लोड होने पर मेन्यू इनिशियलाइज़ करें
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initMainMenu);
  } else {
    initMainMenu();
  }
  // ToolsX Header Search — robust Blogger search fallback.
  // Uses the standard Blogger /search?q= endpoint directly so the header
  // search keeps working even if data:blog.searchUrl is unavailable or
  // another theme script interferes with normal form submission.
  window.tsxHeaderSearch = function(form){
    var input = form ? form.querySelector("input[name='q']") : null;
    if(!input){ return false; }
    var q = (input.value || '').trim();
    if(!q){
      input.focus();
      return false;
    }
    window.location.href = '/search?q=' + encodeURIComponent(q);
    return false;
  };

  // Search Toggle
  var searchToggle = document.querySelector('.zeixilo');
  var searchOverlay = document.getElementById('ijjiIf');
  var searchClose = document.querySelector('.ijjiIf-close');

  if(searchToggle){
    searchToggle.addEventListener('click', function(){
      document.body.classList.add('zeiavilo');
      var input = document.querySelector('.search-input');
      if(input) input.focus();
    });
  }

  var ijjiIfInput = document.querySelector('#ijjiIf .search-input');
  if(ijjiIfInput){
    ijjiIfInput.addEventListener('keydown', function(e){
      if(e.key === 'Enter'){
        e.preventDefault();
        var q = ijjiIfInput.value.trim();
        if(q){
          window.location.href = '/search?q=' + encodeURIComponent(q);
        }
      }
    });
  }

  if(searchClose){
    searchClose.addEventListener('click', function(){
      document.body.classList.remove('zeiavilo');
    });
  }

  // Share Box Toggle
  var shareTop = document.querySelector('.share-top');
  var closeShare = document.querySelector('.close-check');

  if(shareTop){
    shareTop.addEventListener('click', function(){
      document.body.classList.add('show-share');
    });
  }

  if(closeShare){
    closeShare.addEventListener('click', function(){
      document.body.classList.remove('show-share');
    });
  }

  // Copy Link Functionality
  var copyBtn = document.querySelector('.zliciilo button');
  var copyInput = document.getElementById('showlink');

  if(copyBtn && copyInput){
    copyBtn.addEventListener('click', function(){
      copyInput.select();
      document.execCommand('copy');
      var messageDone = document.getElementById('messageDone');
      if(messageDone){
        messageDone.innerHTML = '<span>Link copied to clipboard!</span>';
        setTimeout(function(){messageDone.innerHTML = '';}, 3000);
      }
    });
  }

  // Comment Section Toggle
  var showCommentForm = document.getElementById('show-comment-form');
  var commentSection = document.querySelector('.comment-contentl');

  if(showCommentForm && commentSection){
    showCommentForm.addEventListener('click', function(){
      commentSection.classList.add('comment-section-visible');
      this.style.display = 'none';
    });
  }

      // jQuery हटाने के बाद Slider/Ticker चलाने के लिए (प्योर JS)
      function runSlider(containerSelector, itemSelector, activeClass, interval) {
        var container = document.querySelector(containerSelector);
        if(!container) return;
        var items = container.querySelectorAll(itemSelector);
        if(items.length < 2) return;
        var current = 0;
        items.forEach(function(el, i) { el.classList.toggle(activeClass, i === 0); });
        function isContainerVisible(){
          return container.offsetParent !== null && window.getComputedStyle(container).display !== 'none';
        }
        setInterval(function() {
          if(!isContainerVisible()) return;
          items[current].classList.remove(activeClass);
          current = (current + 1) % items.length;
          items[current].classList.add(activeClass);
        }, interval);
      }
      // होमपेज पर स्लाइडर (4 सेकंड)
      runSlider('.ijoiIf .widget-content', '.ifaiIf', 'active', 4000);
      // ट्रेंडिंग टिकर (5 सेकंड)
      runSlider('.zeitvilo .widget-content', '.itaiIf', 'active', 5000);
// FIX: Mobile menu populate karein aur sub-menu toggle kaam karein
(function() {
  function populateMobileMenu() {
    var desktopMenu = document.getElementById('menutab');
    var mobileContainer = document.getElementById('rRlLmii');
    if (!desktopMenu || !mobileContainer) return;

    var clone = desktopMenu.cloneNode(true);
    mobileContainer.innerHTML = '';
    mobileContainer.appendChild(clone);

    var subItems = mobileContainer.querySelectorAll('li.sub-tab');
    subItems.forEach(function(item) {
      var link = item.querySelector('a');
      if (link) {
        link.addEventListener('click', function(e) {
          e.preventDefault();
          item.classList.toggle('show');
        });
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', populateMobileMenu);
  } else {
    populateMobileMenu();
  }

  var hamburger = document.querySelector('.hamburger');
  if (hamburger) {
    hamburger.addEventListener('click', function() {
      setTimeout(populateMobileMenu, 50);
    });
  }
})();
})();
