(function(){
  // ===== ToolsX: Sticky header on scroll =====
  var header = document.querySelector('.llhbflii');
  if(header){
    var stickyOffset = header.offsetTop;
    // TSXv5 FIX: uses the same shared rAF-throttled scroll dispatcher (see the
    // "Forced reflow" fix earlier in <head>) instead of its own raw scroll
    // listener, so this doesn't add a second separate reflow-triggering
    // listener back in.
    if(window.tsxOnScroll){
      window.tsxOnScroll(function(){
        if(window.pageYOffset > stickyOffset){
          header.classList.add('fixed-nos', 'show');
        } else {
          header.classList.remove('fixed-nos', 'show');
        }
      });
  }
  }

  // ===== ToolsX: Cookie consent popup =====
  var cookieBox = document.getElementById('xliiv');
  if(cookieBox){
    var acceptBtn = cookieBox.querySelector('.xliv:not(.xliv-reject)');
    // FIX (Sep 2026): Reject button - dismisses the banner and records "rejected" instead of "accepted".
    var rejectBtn = cookieBox.querySelector('.xliv-reject');
    var alreadyDecided = false;
    try{ alreadyDecided = ['accepted','rejected'].indexOf(localStorage.getItem('toolsx_cookie_consent')) !== -1; }catch(e){}
    if(alreadyDecided){
      cookieBox.classList.remove('cookies-show');
    } else {
      cookieBox.style.display = 'block';
      setTimeout(function(){ cookieBox.classList.add('cookies-show'); }, 1000);
    }
    function dismiss(choice){
      try{ localStorage.setItem('toolsx_cookie_consent', choice); }catch(e){}
      cookieBox.classList.remove('cookies-show');
      setTimeout(function(){ cookieBox.style.display = 'none'; }, 500);
    }
    if(acceptBtn){ acceptBtn.addEventListener('click', function(){ dismiss('accepted'); }); }
    if(rejectBtn){ rejectBtn.addEventListener('click', function(){ dismiss('rejected'); }); }
  }
})();
